"前面是": "À frente fica",
"前面是「墓园」：雾最浓的地方是镇外的墓园，新坟一夜比一夜多。": "À frente fica o “Cemitério”: a névoa é mais densa ali, e há mais covas novas a cada noite.",
"前面是「总装车间」：工厂最后造出来的东西，把工厂里的人都装了进去。": "À frente fica a “Linha de Montagem”: a última coisa que a fábrica construiu levou para dentro todos que trabalhavam nela.",
"前面是「手术室」：院长说手术很成功，病人只是还没醒。": "À frente fica a “Sala de Cirurgia”: o diretor diz que a cirurgia foi um sucesso — o paciente só ainda não acordou.",
"前面是「海底」：港口下面还有一座城，城门是一张嘴。": "À frente fica o “Fundo do Mar”: há outra cidade sob o porto, e seu portão é uma boca.",
"前面是「知识古树」：古树记得森林里发生过的每一件事，它不想再记住别的了。": "À frente fica a “Árvore do Saber”: ela se lembra de tudo o que já aconteceu na floresta e não quer lembrar de mais nada.",
"前面是「精灵女王」：女王在月池边等了三百年。她说，你就是她等的那个人。": "À frente fica a “Rainha Élfica”: ela esperou à beira do lago da lua por trezentos anos. Diz que você é quem ela esperava.",
"前面是「马戏大棚」：大棚里的笑声从来没停过，只是再也没有观众。": "À frente fica a “Tenda do Circo”: as risadas lá dentro nunca pararam — só não há mais plateia.",
